UPDATE payment
SET charge_id = #{chargeId}
WHERE seq = #{seq}

UPDATE payment
SET 
	status = #{status}
WHERE charge_id = #{orderId}

UPDATE member m
SET m.point = m.point + (
    SELECT p.amount
    FROM payment p
    WHERE p.charge_id = #{orderId}
      AND p.status = 'DONE'
)
WHERE m.seq = (
    SELECT p.member_seq
    FROM payment p
    WHERE p.charge_id = #{orderId}
      AND p.status = 'DONE'
)
